"""
Environment Configuration Schema for Voice Agent

Defines environment variables and configuration for a single agent session
"""

from typing import Any
from typing import Optional

from pydantic import BaseModel
from pydantic import Field
from pydantic import model_validator


class LiveKitConfig(BaseModel):
    """LiveKit connection configuration"""

    url: str = Field(description="LiveKit server URL")
    api_key: str = Field(description="LiveKit API key")
    api_secret: str = Field(description="LiveKit API secret")


class StorageConfig(BaseModel):
    """Storage configuration for recordings"""

    r2_enabled: bool = Field(default=False, description="Enable R2/S3 storage")
    r2_key: Optional[str] = Field(default=None, description="R2/S3 access key")
    r2_secret: Optional[str] = Field(default=None, description="R2/S3 secret key")
    r2_endpoint: Optional[str] = Field(default=None, description="R2/S3 endpoint URL")
    r2_bucket: str = Field(default="voice-recordings", description="R2/S3 bucket name")
    local_output_dir: Optional[str] = Field(
        default=None, description="Local directory for recordings (default: conversation_logs)"
    )

    @model_validator(mode="after")
    def validate_r2_config(self) -> "StorageConfig":
        """Validate R2 configuration if enabled"""
        if self.r2_enabled:
            if not all([self.r2_key, self.r2_secret, self.r2_endpoint]):
                raise ValueError(
                    "R2 storage enabled but missing required credentials (r2_key, r2_secret, r2_endpoint)"
                )
        return self


class RecordingSettings(BaseModel):
    """Recording and persistence settings"""

    enable_recording: bool = Field(
        default=True, description="Enable room composite egress recording"
    )
    enable_persistence: bool = Field(
        default=True, description="Enable transcript persistence to files"
    )
    audio_only: bool = Field(default=True, description="Record audio only (no video)")
    transcripts_only: bool = Field(
        default=False, description="Only persist transcripts, not events"
    )


class EnvironmentConfig(BaseModel):
    """Complete environment configuration for Voice Agent session"""

    # LiveKit configuration
    livekit: LiveKitConfig = Field(description="LiveKit connection configuration")

    # Storage configuration
    storage: StorageConfig = Field(
        default_factory=StorageConfig, description="Storage configuration for recordings"
    )

    # Recording settings
    recording: RecordingSettings = Field(
        default_factory=RecordingSettings, description="Recording and persistence settings"
    )

    # Session identification
    room_name: Optional[str] = Field(
        default=None, description="Room name for this session (auto-detected if not provided)"
    )

    @classmethod
    def from_environment(cls, environ: dict[str, Any]) -> "EnvironmentConfig":
        """
        Create configuration from environment variables

        Supports both voice agent specific and fallback to main agent variables
        """
        config_dict = {}

        # Try to get LiveKit credentials
        livekit_url = environ.get("VOICE_AGENT_LIVEKIT_URL") or environ.get("LIVEKIT_URL_INBOUND")
        livekit_key = environ.get("VOICE_AGENT_LIVEKIT_API_KEY") or environ.get("LIVEKIT_API_KEY_INBOUND")
        livekit_secret = environ.get("VOICE_AGENT_LIVEKIT_API_SECRET") or environ.get("LIVEKIT_API_SECRET_INBOUND")

        if not all([livekit_url, livekit_key, livekit_secret]):
            # Try loading from agent.env as fallback
            try:
                from agent.env import env as agent_env
                livekit_url = livekit_url or agent_env.LIVEKIT_URL_INBOUND
                livekit_key = livekit_key or agent_env.LIVEKIT_API_KEY_INBOUND
                livekit_secret = livekit_secret or agent_env.LIVEKIT_API_SECRET_INBOUND
            except ImportError:
                pass

        if not all([livekit_url, livekit_key, livekit_secret]):
            raise ValueError(
                "LiveKit credentials not found. Set VOICE_AGENT_LIVEKIT_* or LIVEKIT_*_INBOUND environment variables"
            )

        config_dict["livekit"] = {
            "url": livekit_url,
            "api_key": livekit_key,
            "api_secret": livekit_secret,
        }

        # Storage configuration
        storage_config = {
            "r2_enabled": False,
            "local_output_dir": environ.get("VOICE_AGENT_RECORDING_OUTPUT_DIR"),
        }

        # Check for R2 credentials
        r2_key = environ.get("VOICE_AGENT_R2_KEY") or environ.get("R2_KEY")
        r2_secret = environ.get("VOICE_AGENT_R2_SECRET") or environ.get("R2_SECRET")
        r2_endpoint = environ.get("VOICE_AGENT_R2_ENDPOINT") or environ.get("R2_ENDPOINT")

        if not all([r2_key, r2_secret, r2_endpoint]):
            # Try loading from agent.env as fallback
            try:
                from agent.env import env as agent_env
                r2_key = r2_key or agent_env.R2_KEY
                r2_secret = r2_secret or agent_env.R2_SECRET
                r2_endpoint = r2_endpoint or agent_env.R2_ENDPOINT
            except ImportError:
                pass

        if all([r2_key, r2_secret, r2_endpoint]):
            storage_config.update({
                "r2_enabled": True,
                "r2_key": r2_key,
                "r2_secret": r2_secret,
                "r2_endpoint": r2_endpoint,
                "r2_bucket": environ.get("VOICE_AGENT_R2_BUCKET", "voice-recordings"),
            })

        config_dict["storage"] = storage_config

        # Recording settings
        config_dict["recording"] = {
            "enable_recording": environ.get("VOICE_AGENT_ENABLE_RECORDING", "true").lower() == "true",
            "enable_persistence": environ.get("VOICE_AGENT_ENABLE_PERSISTENCE", "true").lower() == "true",
            "audio_only": environ.get("VOICE_AGENT_AUDIO_ONLY", "true").lower() == "true",
            "transcripts_only": environ.get("VOICE_AGENT_TRANSCRIPTS_ONLY", "false").lower() == "true",
        }

        # Room name if provided
        room_name = environ.get("VOICE_AGENT_ROOM_NAME")
        if room_name:
            config_dict["room_name"] = room_name

        return cls.model_validate(config_dict)

    def get_storage_dict(self) -> dict:
        """Get storage configuration as dictionary for egress service"""
        if not self.storage.r2_enabled:
            return {}

        return {
            "r2_enabled": True,
            "r2_key": self.storage.r2_key,
            "r2_secret": self.storage.r2_secret,
            "r2_endpoint": self.storage.r2_endpoint,
            "r2_bucket": self.storage.r2_bucket,
        }

